from typing import List, Union

class LookupErr:
    def __init__(self, NotFound: str = "", EmptyCollection: bool = False):
        self.NotFound = NotFound
        self.EmptyCollection = EmptyCollection

    def __repr__(self):
        if self.EmptyCollection:
            return "LookupErr(EmptyCollection=True)"
        return f"LookupErr(NotFound={self.NotFound!r})"

def safeStackPop(stack: List[int]) -> Union[List[int], LookupErr]:
    if len(stack) == 0:
        return LookupErr(EmptyCollection=True)

    p = stack.copy()
    q = len(p)
    if q > 0:
        p.pop()
    return p

def main():
    test_cases = [
        [1, 2, 3, 4, 5],
        [10],
        [],
        [0, 0, 0],
        [-5, 0, 5]
    ]

    for i, stack in enumerate(test_cases):
        result = safeStackPop(stack)
        print(f"Test {i+1}: {stack} -> {result}")

if __name__ == "__main__":
    main()

