#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    char* NotFound;
    bool EmptyCollection;
} LookupErr;

typedef struct {
    int* data;
    size_t len;
} i64Array;

typedef struct {
    bool is_error;
    union {
        i64Array ok;
        LookupErr err;
    } value;
} Result;

Result safeStackPop(i64Array stack) {
    Result result;

    if (stack.len == 0) {
        result.is_error = true;
        result.value.err.EmptyCollection = true;
        result.value.err.NotFound = NULL;
        return result;
    }

    i64Array q;
    q.len = stack.len - 1;
    q.data = (int*)malloc(q.len * sizeof(int));
    if (q.data == NULL) {
        result.is_error = true;
        result.value.err.EmptyCollection = false;
        result.value.err.NotFound = strdup("Memory allocation failed");
        return result;
    }

    for (size_t p = 0; p < q.len; p++) {
        q.data[p] = stack.data[p];
    }

    result.is_error = false;
    result.value.ok = q;
    return result;
}

void printArray(i64Array arr) {
    printf("[");
    for (size_t i = 0; i < arr.len; i++) {
        printf("%d", arr.data[i]);
        if (i < arr.len - 1) printf(", ");
    }
    printf("]");
}

void freeResult(Result* r) {
    if (!r->is_error) {
        free(r->value.ok.data);
    } else {
        if (r->value.err.NotFound != NULL) {
            free(r->value.err.NotFound);
        }
    }
}

int main() {
    i64Array test1 = { (int[]){1, 2, 3, 4, 5}, 5 };
    i64Array test2 = { (int[]){42}, 1 };
    i64Array test3 = { (int[]){0, 0, 0}, 3 };
    i64Array test4 = { (int[]){-1, -2, -3}, 3 };
    i64Array test5 = { NULL, 0 };

    Result r1 = safeStackPop(test1);
    if (!r1.is_error) {
        printArray(r1.value.ok);
        printf("\n");
    } else {
        printf("Error: EmptyCollection=%d\n", r1.value.err.EmptyCollection);
    }

    Result r2 = safeStackPop(test2);
    if (!r2.is_error) {
        printArray(r2.value.ok);
        printf("\n");
    } else {
        printf("Error: EmptyCollection=%d\n", r2.value.err.EmptyCollection);
    }

    Result r3 = safeStackPop(test3);
    if (!r3.is_error) {
        printArray(r3.value.ok);
        printf("\n");
    } else {
        printf("Error: EmptyCollection=%d\n", r3.value.err.EmptyCollection);
    }

    Result r4 = safeStackPop(test4);
    if (!r4.is_error) {
        printArray(r4.value.ok);
        printf("\n");
    } else {
        printf("Error: EmptyCollection=%d\n", r4.value.err.EmptyCollection);
    }

    Result r5 = safeStackPop(test5);
    if (!r5.is_error) {
        printArray(r5.value.ok);
        printf("\n");
    } else {
        printf("Error: EmptyCollection=%d\n", r5.value.err.EmptyCollection);
    }

    freeResult(&r1);
    freeResult(&r2);
    freeResult(&r3);
    freeResult(&r4);
    freeResult(&r5);

    return 0;
}

